package dev.veltraph.client.navigation;
import dev.veltraph.client.core.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LegacyParentCleanupStoredRoleTest {
 static class Controller extends AbstractModule {boolean passive;int reads;Controller(String id){super(id,id,ModuleCategory.MISC);}public boolean isPassiveObserver(){reads++;return passive;}}
 @Test void nativeConsumedProducerChecksOnlyExistingActualFinalFields(){var root=new ModuleManager();var p=new Controller("p");root.register(p);p.setEnabled(true);assertTrue(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,root.lifecycleSnapshot(),p));assertEquals(0,p.reads);}
 @Test void lateCameraMutatesEnabledPassiveRoleWithoutLifecycleChangeAndScopedProofRefuses(){var root=new ModuleManager();var p=new Controller("p");var observer=new Controller("observer");observer.passive=true;root.register(p);root.register(observer);p.setEnabled(true);observer.setEnabled(true);var snap=root.lifecycleSnapshot();assertEquals(1,root.enabledControllers().size());Runnable camera=()->observer.passive=false;camera.run();assertTrue(root.lifecycleCurrent(snap));assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,snap,p));}
 @Test void observerDenialDoesNotChangeOrdinaryGeneralControllerSelection(){var root=new ModuleManager();var p=new Controller("p");var observer=new Controller("observer");observer.passive=true;root.register(p);root.register(observer);p.setEnabled(true);observer.setEnabled(true);assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,root.lifecycleSnapshot(),p));assertEquals(1,root.enabledControllers().size());assertTrue(observer.isEnabled());}
 @Test void lateForeignEnableRevokesTheActualSnapshot(){var root=new ModuleManager();var p=new Controller("p");var q=new Controller("q");root.register(p);root.register(q);p.setEnabled(true);var snap=root.lifecycleSnapshot();q.setEnabled(true);assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,snap,p));}
 @Test void privateEnableAbaAndSupplierReplacementRevoke(){var root=new ModuleManager();var p=new Controller("p");root.register(p);p.setEnabled(true);var snap=root.lifecycleSnapshot();p.setEnabled(false);p.setEnabled(true);assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,snap,p));snap=root.lifecycleSnapshot();root.leasedInputOwner(()->p);assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,snap,p));}
 @Test void wrongRegisteredParentOrMissingCurrentEnabledOwnerRefuses(){var root=new ModuleManager();var p=new Controller("p");root.register(p);p.setEnabled(true);assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,root.lifecycleSnapshot(),new Controller("other")));p.setEnabled(false);assertFalse(LegacyParentCleanupReentryIdentity.storedOnlyEnabled(root,root.lifecycleSnapshot(),p));}
}
